from pathlib import Path
import re,json
root=Path(__file__).parent
frames=root/'frames'
def icon(name,size=20): return f'<img class="icon" src="../assets/icons/{name}Icon.svg" width="{size}" height="{size}" alt="" aria-hidden="true">'
def docicon(name): return icon(name).replace('../assets/','assets/')
def body(path): return re.search(r'<body[^>]*>([\s\S]*?)</body>',Path(path).read_text(encoding='utf-8-sig'))[1]
source=body('quiet-assembly/frames/01-list.html')
cards=re.findall(r'<article class="event-card".*?</article>',source,re.S)
ink=cards[2].replace('href="01-event.html"','href="01-event.html"')
appbar=f'<header class="appbar"><a class="brand" href="01-list.html" aria-label="Burque events">BURQUE<span aria-hidden="true">.</span></a><a class="saved-label" href="saved.html">{icon("Bookmark")}Saved</a></header>'
def page(file,title,content,foot=True):
 html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#111517"><title>{title} · Date Line</title><link rel="preload" href="../assets/fonts/manrope-latin-wght-normal.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="../fonts.css"><link rel="stylesheet" href="../screens.css"><link rel="stylesheet" href="../themes.css"><link rel="stylesheet" href="../cards.css"><link rel="stylesheet" href="../ui.css"></head><body class="screen kit-screen" data-study="01" data-layout="line">{appbar}<main>{content}</main>'''
 if foot: html+='<footer class="screen-footer"><span>Design sample · fictional details</span><a href="../index.html#screens" target="_top">Back to UI kit</a></footer>'
 html+='</body></html>'; (frames/file).write_text(html,encoding='utf-8')
def intro(kicker,title,text=''):
 return f'<div class="page-intro"><p class="kicker">{kicker}</p><h1>{title}</h1>'+(f'<p>{text}</p>' if text else '')+'</div>'
def field(id,label,value='',typ='text',note='',attrs=''):
 return f'<div class="field"><label for="{id}">{label}</label><input id="{id}" type="{typ}" value="{value}" {attrs}'+(f' aria-describedby="{id}-note"' if note else '')+'>'+ (f'<small id="{id}-note">{note}</small>' if note else '')+'</div>'
search=intro('Discover','Find an event.')+f'''<div class="page-body stack"><form action="search.html" class="field" role="search"><label for="event-search">Search events, venues or neighborhoods</label><div class="search-line"><input id="event-search" type="search" value="printmaking"><button class="btn" aria-label="Search events">{icon('ArrowRight')}</button></div></form><div class="row" style="justify-content:space-between"><a class="chip selected" href="filters.html">{icon('Calendar',16)}This weekend</a><a class="text-link" href="filters.html">Filters (1)</a></div><p class="fine">Albuquerque · All neighborhoods</p></div><div class="result-label"><span>1 event</span><span>Workshops</span></div><section class="event-list" aria-label="Search results">{ink}</section><div class="page-body spaced"><a class="text-link" href="01-list.html">Browse all events</a></div>'''
page('search.html','Search events',search)
filters=intro('Discover','Make it your evening.','A few choices to narrow things down.')+'''<form action="search.html" class="page-body"><fieldset class="form-section"><legend>When</legend><div class="chips"><label class="chip"><input type="radio" name="when" value="today">Today</label><label class="chip"><input type="radio" name="when" value="tomorrow">Tomorrow</label><label class="chip"><input type="radio" name="when" value="weekend" checked>This weekend</label><label class="chip"><input type="radio" name="when" value="any">Any time</label></div><p class="fine">Friday, October 23 – Saturday, October 24</p></fieldset><fieldset class="form-section"><legend>What are you into?</legend><label class="native-choice"><input type="checkbox">Music</label><label class="native-choice"><input type="checkbox">Comedy</label><label class="native-choice"><input type="checkbox">Workshops</label><label class="native-choice"><input type="checkbox">Art &amp; culture</label><label class="native-choice"><input type="checkbox">Food &amp; drink</label></fieldset><fieldset class="form-section"><legend>Price</legend><label class="native-choice"><input type="radio" name="price" checked>Any price</label><label class="native-choice"><input type="radio" name="price">Free events only</label></fieldset><div class="form-actions"><button class="btn full">Show matching events</button><button class="btn quiet full" type="reset">Reset choices</button><a class="btn secondary full" href="search.html">Cancel</a></div></form>'''
page('filters.html','Filters',filters)
page('saved.html','Saved evenings',intro('Your shortlist','Saved evenings.','Two plans worth keeping.')+f'<div class="result-label"><span>2 saved events</span><span>This weekend</span></div><section class="event-list" aria-label="Saved events">{cards[0]}{ink}</section><div class="page-body spaced"><p class="fine">Saved on this device. No account needed.</p><a class="text-link" href="01-list.html">Keep exploring</a></div>')
page('saved-empty.html','No saved events',intro('Your shortlist','Saved evenings.')+f'<section class="empty">{icon("Bookmark")}<h2>A little space for<br>your next good plan.</h2><p>Save an event that catches your eye. It will be waiting here when you come back.</p><a class="btn" href="01-list.html">Explore events{icon("ArrowRight")}</a></section>')
page('no-results.html','No results',intro('Discover','Nothing quite matches.')+'''<section class="empty"><p>There aren’t any printmaking events in this date range. Try another weekend or broaden your search.</p><div class="chips"><span class="chip selected">Printmaking</span><span class="chip selected">This weekend</span></div><a class="btn" href="filters.html">Adjust filters</a><a class="text-link" href="search.html">Clear the search</a></section>''')
submit=intro('For organizers','Share an evening.','A local event, in your own words.')+'''<form action="review.html" class="page-body"><p class="fine">All fields are required unless marked optional.</p><section class="form-section"><h2>The essentials</h2>'''
submit+=field('event-title','Event title','Ink After Dark',attrs='required maxlength="120"')
submit+='''<div class="field"><label for="category">Category</label><select id="category" required><option>Music</option><option>Comedy</option><option selected>Workshop</option><option>Art &amp; culture</option><option>Food &amp; drink</option></select></div><div class="field"><label for="description">What’s the evening like?</label><textarea id="description" aria-describedby="description-note" required>Carve a simple block, pull your first print, and settle into an easygoing evening around a shared studio table. All materials and tools are included.</textarea><small id="description-note">Help someone decide whether this is for them. Include age limits and useful access information.</small></div></section><section class="form-section"><h2>When &amp; where</h2>'''
submit+=field('date','Date','2026-10-24','date',attrs='required')
submit+='<div class="split">'+field('start','Starts','18:00','time',attrs='required')+field('end','Ends · optional','20:00','time')+'</div>'
submit+=field('venue','Venue','Barelas Print Studio',attrs='required')
submit+=field('address','Street address','123 Sample Street SW',note='Fictional address for this design sample.',attrs='required')
submit+='</section><section class="form-section"><h2>Admission</h2>'
submit+=field('price','Price per person','32','number',note='Enter 0 for a free event.',attrs='required min="0" step="0.01"')
submit+=field('tickets','Tickets or RSVP link · optional','https://example.com/ink-after-dark','url',note='Send people to the official organizer or ticket page.')
submit+='</section><section class="form-section"><h2>A photo · optional</h2><div class="upload-field"><label for="photo">Choose an event photo</label><input id="photo" aria-describedby="photo-note" type="file" accept="image/jpeg,image/png,image/webp"><p id="photo-note" class="fine">JPG, PNG or WebP. Up to 10 MB. No photo? Your event will still have a clear, well-designed listing.</p></div></section><section class="form-section"><h2>Who’s hosting?</h2>'
submit+=field('organizer','Organizer name','Barelas Print Studio',attrs='required')
submit+=field('email','Contact email','hello@example.com','email',note='For review questions. This email won’t be published.',attrs='required')
submit+='</section><div class="form-actions"><button class="btn full">Review event'+icon('ArrowRight')+'</button><a class="btn secondary full" href="01-list.html">Cancel</a></div></form>'
page('submit.html','Submit an event',submit)
review=intro('For organizers · Review','Looks like a good evening.','Check the details before sending your event for review.')+f'''<section class="fallback-panel" aria-label="Event preview without a photograph"><p class="missing-label">No photo added</p><span class="category">Workshop</span><h2>Ink After Dark</h2><p class="muted">Barelas Print Studio</p></section><div class="page-body spaced stack"><div class="row" style="justify-content:space-between"><h2>Event details</h2><a class="text-link" href="submit.html">Edit</a></div><dl class="summary-list"><div><dt>When</dt><dd>Saturday, October 24<br>6:00–8:00 PM</dd></div><div><dt>Where</dt><dd>Barelas Print Studio<br>123 Sample Street SW<br>Albuquerque, NM</dd></div><div><dt>Price</dt><dd>$32 · Materials included</dd></div><div><dt>Organizer</dt><dd>Barelas Print Studio</dd></div><div><dt>Contact</dt><dd>hello@example.com<br><span class="fine">Private · not published</span></dd></div></dl><section class="form-section"><h2>About the evening</h2><p class="muted">Carve a simple block, pull your first print, and settle into an easygoing evening around a shared studio table. All materials and tools are included.</p></section><div class="notice"><strong>A quick review before it goes live</strong><p>We’ll check the event details and contact you if anything needs a second look.</p></div><a class="btn full" href="received.html">Submit for review{icon('ArrowRight')}</a><a class="btn secondary full" href="submit.html">Back to editing</a></div>'''
page('review.html','Review event',review)
page('received.html','Event received',intro('For organizers','Thanks for sharing.')+f'''<section class="empty">{icon('Check')}<span class="badge warning" style="justify-self:start">Pending review</span><h2>Your evening is<br>in good hands.</h2><p><strong>Ink After Dark</strong> has been sent for review. It isn’t public yet.</p><p>We’ll send an update to <strong>hello@example.com</strong> when it’s ready, or if we need more information.</p><a class="btn" href="01-list.html">Back to events{icon('ArrowRight')}</a></section>''')
# Received is a static state fixture, never a live submission confirmation. This is disclosed on the library canvas.
states=intro('The everyday realities','Room for real life.','Quiet, reusable patterns for the moments between the happy paths.')+f'''<section class="page-body stack"><div class="notice error"><strong>We couldn’t load more events.</strong><p>Your earlier results are still here. Check your connection and try again.</p><a class="text-link" href="search.html">Try again</a></div><div class="notice"><strong>The time has changed.</strong><p>Ink After Dark now starts at 6:30 PM. Check the latest details before heading out.</p></div><div class="notice error"><strong>This event has been cancelled.</strong><p>The organizer has cancelled this evening. Contact them about any tickets you purchased.</p></div><div class="notice"><strong>This evening is sold out.</strong><p>You can still save it and check the organizer’s page for availability.</p></div><div class="toast-sample"><span>Event saved to your evenings.</span><a href="saved.html">View</a></div></section><section class="state-block"><div class="empty"><h2>This event is<br>no longer available.</h2><p>It may have been removed by its organizer. There are other good evenings to discover.</p><a class="btn secondary" href="01-list.html">Explore events</a></div></section>'''
page('states.html','Event states',states)
# Main library: composition-focused documentation, with production-independent tokens.
nav='''<aside class="kit-nav"><a class="brand" href="#top">BURQUE<span aria-hidden="true">.</span></a><p class="edition">DATE LINE · UI KIT / 0.1</p><nav aria-label="UI kit sections"><a href="#foundations"><span>01</span>Foundations</a><a href="#components"><span>02</span>Components</a><a href="#screens"><span>03</span>Screens</a><a href="#coverage"><span>04</span>Coverage</a></nav><p class="nav-foot">A quiet system for<br>good local evenings.<br><br>Static HTML · 22 Oct 2026</p></aside>'''
hero=f'''<header class="kit-hero" id="top"><div><p class="kicker">Date Line / Interface library</p><h1>The same feeling.<br>Everywhere.</h1><p class="lead">A considered foundation for everything around the event. Built from the Date Line you chose, with the original list and full-screen event preserved.</p><div class="row" style="margin-top:28px"><a class="btn" href="#screens">Explore the screens{docicon('ArrowRight')}</a><a class="btn quiet" href="01-date-line.html">View the original</a></div></div><div class="hero-card">{ink.replace('../assets/','assets/').replace('href="01-event.html"','href="frames/01-event.html"')}<p class="hero-card-label">THE ANCHOR / Original card anatomy, unchanged</p></div></header>'''
def heading(num,title,note):return f'<div class="section-heading"><div><p class="kicker">{num}</p><h2>{title}</h2></div><p>{note}</p></div>'
colors=[('Canvas','#111517'),('Card','#1a1f22'),('Raised','#232a2e'),('Primary text','#f0f1ed'),('Secondary text','#b8bfc6'),('Accent','#edbd8b')]
swatches=''.join(f'<div><div class="swatch" style="background:{color}"></div><p class="swatch-label">{name}<code>{color.upper()}</code></p></div>' for name,color in colors)
foundations=heading('01 / Foundations','One visual language.','Keep the distinct parts of Date Line. Introduce only the tokens the rest of the product needs.')+f'''<div class="doc-grid"><article class="doc-panel"><h3>The palette</h3><p class="fine">Warm action. Cool surfaces. Three useful levels of depth.</p><div class="swatches">{swatches}</div></article><article class="doc-panel"><h3>Manrope, throughout</h3><p class="fine">A single family. Body 14/24; form values 16/24. Scale, weight and space establish hierarchy.</p><div class="type-row"><p style="font-size:36px;line-height:40px;font-weight:580;letter-spacing:-.04em">Ink After Dark</p><small>Event title · 36 / 40 · 580</small></div><div class="type-row"><p style="font-size:28px;line-height:36px;font-weight:580;letter-spacing:-.032em">Saved evenings.</p><small>Page title · 28 / 36 · 580</small></div><div class="type-row"><p style="font-size:24px;line-height:32px;font-weight:580;letter-spacing:-.032em">Desert Frequencies</p><small>Card title · 24 / 32 · 580</small></div><div class="type-row"><p>Small rooms. Good company. A local evening.</p><small>Body · 14 / 24 · 400</small></div></article><article class="doc-panel"><h3>Space with a rhythm</h3><p class="fine">A 4px base. Prefer a small set of deliberate intervals.</p>'''+''.join(f'<div class="space-row"><span>{v}px</span><div class="space-bar" style="width:{v*4}px;max-width:100%"></div><span>{role}</span></div>' for v,role in [(4,'Tight'),(8,'Inline'),(12,'Fields'),(16,'Group'),(24,'Inset'),(32,'Section'),(48,'Break')])+'''</article><article class="doc-panel"><h3>The rules that hold it together</h3><p class="fine">Extensions inherit the visual structure of the original.</p><ol class="rule-list"><li>24px page insets. Cards meet edge to edge, with fine dividing rules.</li><li>Dots belong to event surfaces. Forms and reading areas stay calm and plain.</li><li>One peach primary action per task. Secondary actions use an outline or a text link.</li><li>48px form controls; 44px icon targets. Radius: 8px fields, 12px actions, 16px documentation panels.</li><li>Visible labels and focus rings. Meaningful status words accompany every status color.</li><li>Long titles wrap. Missing facts stay unknown. A poor photo never carries the reading hierarchy.</li></ol></article></div>'''
components=heading('02 / Components','A small, useful kit.','The parts a real event site needs, with restrained states and shared proportions. Native controls work; these are isolated specimens, not connected app features.')+f'''<div class="doc-grid"><article class="doc-panel"><h3>Actions &amp; navigation</h3><p class="fine">A clear priority. No competing accent treatments.</p><div class="stack"><a class="btn" href="frames/01-event.html">View event{docicon('ArrowRight')}</a><a class="btn secondary" href="frames/search.html">Explore events</a><button class="btn" disabled>Unavailable</button></div><p class="component-label">Icon controls · rest / selected / focus</p><div class="row"><a class="icon-btn" href="frames/01-list.html" aria-label="Close example">{docicon('Cross1')}</a><a class="icon-btn selected" href="frames/saved.html" aria-label="Saved example">{docicon('Bookmark')}</a><a class="icon-btn demo-focus" href="frames/01-list.html" aria-label="Back example">{docicon('ArrowLeft')}</a></div><p class="component-label">Filter choices</p><div class="chips"><span class="chip selected">This weekend</span><a class="chip" href="frames/filters.html">Free events</a></div></article><article class="doc-panel"><h3>Fields &amp; choices</h3><p class="fine">Labels remain visible. Errors say what to do next.</p><div class="stack">'''+field('specimen-title','Event title','Ink After Dark')+field('specimen-venue','Venue','',note='Enter the venue name so people know where to go.',attrs='aria-invalid="true"')+'''<div class="field"><label for="specimen-disabled">City</label><input id="specimen-disabled" value="Albuquerque" disabled><small>Disabled field example.</small></div><label class="native-choice"><input type="checkbox" checked>Free events only</label><fieldset><legend class="sr-only">Example date choices</legend><label class="native-choice"><input type="radio" name="example-date" checked>This weekend</label><label class="native-choice"><input type="radio" name="example-date">Any time</label></fieldset></div></article><article class="doc-panel"><h3>Status, without shouting</h3><p class="fine">Words do the explaining. Color is a supporting cue.</p><div class="row"><span class="badge success">Published</span><span class="badge warning">Pending review</span><span class="badge danger">Cancelled</span><span class="badge">Sold out</span><span class="badge">Time changed</span></div><p class="component-label">Recovery message</p><div class="notice error"><strong>We couldn’t save that change.</strong><p>Your event details are still here. Try again when your connection returns.</p></div><p class="component-label">Brief feedback</p><div class="toast-sample"><span>Saved to your evenings.</span><a href="frames/saved.html">View</a></div></article><article class="doc-panel"><h3>Trust &amp; practical details</h3><p class="fine">The useful layers below the event opening.</p><div class="organizer"><div><p class="fine">HOSTED BY</p><strong>Barelas Print Studio</strong></div><p class="muted">Questions about materials, access or your booking? Ask the organizer.</p><a class="text-link" href="mailto:hello@example.com">Contact organizer</a></div><p class="component-label">Sponsored placement</p><aside class="partner" aria-label="Sponsored example"><span class="partner-label">Sponsored · Local partner</span><h3>Make a night of the neighborhood.</h3><p>A clearly labelled local offer. Kept separate from event content.</p></aside></article></div>'''
specs=[('search.html','Search & results','Find by event, venue or neighborhood.','New'),('filters.html','Filters','Date, category and price in one calm view.','New'),('saved.html','Saved events','The existing card becomes a personal shortlist.','New'),('saved-empty.html','Empty saved list','A useful next step, with room to breathe.','State'),('submit.html','Submit an event','A longer form built from the same measured parts.','New'),('review.html','Review before sending','A no-photo event preview and clear factual summary.','New'),('received.html','Submission received','Pending review is distinct from published.','State'),('states.html','Recovery & event status','Cancelled, sold out, changed, unavailable and retry.','States')]
screens=heading('03 / Screens','The kit, in context.','Static HTML compositions. Scroll inside each frame or open it separately. Form values and results are fixed design fixtures; no data is submitted or saved.')+'<div class="notice" style="margin-bottom:32px"><strong>The originals stay exactly as you chose them.</strong><p><a href="frames/01-list.html">Original list</a> · <a href="frames/01-event.html">Original full-screen event</a>. These copies retain their original HTML, CSS and artwork. New screens below use the same foundations.</p></div><div class="screen-grid">'
for file,title,note,kind in specs:
 screens+=f'<figure class="screen-study"><figcaption><div><p class="kicker">{kind}</p><h3>{title}</h3><p>{note}</p></div><a href="frames/{file}" target="_blank" rel="noopener" aria-label="Open {title}">{docicon("ExternalLink")}</a></figcaption><iframe loading="lazy" src="frames/{file}" title="{title} static screen"></iframe></figure>'
screens+='</div><p class="fine" style="margin-top:32px">Additional discovery state: <a href="frames/no-results.html">No matching results</a>.</p>' 
rows=[('Browse & event','The selected list, full-screen photo opening and scrolling details.','Preserved'),('Discover','Search, date/category/price filters, no matching results.','Layouts included'),('Save & return','Saved list and empty state. Later: persistence, unsave and save failure.','Layouts included'),('Attend','Event-specific Get tickets / RSVP / Visit organizer, external handoff and sold-out/cancelled actions.','Next screen pass'),('Organizer submission','Required fields, optional photo, review and pending-review confirmation.','Layouts included'),('Manage an event','Private edit link or sign-in, drafts, published status, edits and cancellation.','Next screen pass'),('Content resilience','Poor uploads, no photo, text-heavy posters, long titles, unknown venue/access details.','Existing + no-photo sample'),('Trust & recovery','Organizer/contact, address/directions, share/calendar, report incorrect details, unavailable and connection failure.','Patterns + remaining flows'),('Administration','Review queue, approve/reject, duplicate/spam reports and corrections.','Before public submissions'),('Account & notifications','Cross-device saved events, profiles, preferences and reminders.','Defer until useful')]
coverage=heading('04 / Coverage','What else belongs in the product?','A screen map, not a commitment to build every feature. Keep the first release focused on finding an event and trusting its details.')+'<table class="coverage"><thead><tr><th scope="col">Area</th><th scope="col">Needed coverage</th><th scope="col">Where it stands</th></tr></thead><tbody>'+''.join(f'<tr><td>{a}</td><td>{b}</td><td>{c}</td></tr>' for a,b,c in rows)+'</tbody></table>'+'''<div class="doc-grid" style="margin-top:32px"><article class="doc-panel"><h3>Build next</h3><p class="muted">Refine discovery and the attendance handoff first. Then the organizer submission and correction loop. Those journeys make the minimal interface useful and keep the listings trustworthy.</p></article><article class="doc-panel"><h3>Decisions to keep open</h3><p class="muted">External tickets or native RSVP? Who reviews submissions? How does an organizer edit an event? Those choices determine the next screens. An account wall and a permanent bottom navigation can wait.</p></article></div>'''
html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#111517"><title>Date Line — UI kit</title><link rel="preload" href="assets/fonts/manrope-latin-wght-normal.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="fonts.css"><link rel="stylesheet" href="screens.css"><link rel="stylesheet" href="themes.css"><link rel="stylesheet" href="cards.css"><link rel="stylesheet" href="ui.css"></head><body class="library" data-study="01" data-layout="line"><a class="skip-link" href="#content">Skip to the library</a>{nav}<main class="kit-content" id="content">{hero}<section class="kit-section" id="foundations">{foundations}</section><section class="kit-section" id="components">{components}</section><section class="kit-section" id="screens">{screens}</section><section class="kit-section" id="coverage">{coverage}</section><footer class="kit-footer"><p>Date Line / UI kit 0.1 · Static HTML. No motion, application state, submission service or account system.</p><p>Source of truth: the approved Date Line frames. <a href="README.md">Implementation notes</a> · <a href="tokens.json">Design tokens</a> · <a href="screen-map.json">Screen map</a></p></footer></main></body></html>'''
# Relative icon paths in the two field specimens are absent; only standalone icons were converted above.
(root/'index.html').write_text(html,encoding='utf-8')
(root/'screen-map.json').write_text(json.dumps([{'area':a,'coverage':b,'status':c} for a,b,c in rows],indent=2)+'\n')
tokens={'name':'Date Line','version':'0.1','font':{'family':'Manrope','field':{'size':16,'lineHeight':24,'weight':400},'body':{'size':14,'lineHeight':24,'weight':400},'cardTitle':{'size':24,'lineHeight':32,'weight':580,'tracking':'-.032em'},'pageTitle':{'size':28,'lineHeight':36,'weight':580},'eventTitle':{'size':36,'lineHeight':40,'weight':580,'tracking':'-.04em'}},'colors':dict(colors),'semantic':{'success':'#b3d2bb','warning':'#e4c48f','danger':'#e6b1ad','field':'#171d20','controlBorder':'#68747d'},'space':[4,8,12,16,20,24,28,32,40,48],'inset':24,'cardGap':0,'controls':{'iconTarget':44,'fieldHeight':48,'actionHeight':48},'radius':{'field':8,'action':12,'documentationPanel':16},'texture':{'source':'assets/images/quiet-dots.png','size':720,'opacity':.24},'originalFiles':['frames/01-list.html','frames/01-event.html','screens.css','themes.css','cards.css','fonts.css']}
(root/'tokens.json').write_text(json.dumps(tokens,indent=2)+'\n')
print('Built static UI library, 9 companion screens and screen map. Approved frames untouched.')
